-- T-102 increment 3 (generated by /data/tmp/clinic-dashboard/t102/inc3/gen.py; addendum docs/tasks/T-102.md)
-- T-102 increment 3 (PR-35, UX-23 17:62 / :174, 19:222, 07:63; plan r4 §9): the SATUSEHAT page's readers. Bound, the actor lock first; the
-- projection follows the role (07 :63): owner, manager, facility head, records officer read the branch's monitor (codes only); the facility
-- head and the records officer the identity queue and no-room visits; the owner and the facility head the practitioner and service-map
-- lists; Admin Pusat counts only; a doctor only his own signed visits. The provider's error body (clinical class, DATA-40) only to the
-- facility head. Nothing clinical, no NIK, no secret in any projection.

CREATE FUNCTION public.satusehat_page(p_branch uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  a record := public.satusehat_actor(ARRAY['owner','admin_pusat','manager','facility_head','records_officer','doctor']);
  v_env text := public.satusehat_env();
  v_out jsonb;
  v_counts jsonb;
BEGIN
  PERFORM public.satusehat_branch(a, p_branch);
  v_counts := jsonb_build_object(
    'outbox', (SELECT coalesce(jsonb_object_agg(s, n), '{}'::jsonb) FROM (SELECT x.state || coalesce(':' || x.hold_reason, '') s, count(*) n
               FROM public.satusehat_outbox x WHERE x.tenant_id = a.tenant_id AND x.branch_id = p_branch AND x.state <> 'superseded' GROUP BY 1) q),
    'links', (SELECT coalesce(jsonb_object_agg(s, n), '{}'::jsonb) FROM (SELECT l.status || coalesce(':' || l.status_reason, '') s, count(*) n
               FROM public.satusehat_links l WHERE l.tenant_id = a.tenant_id AND l.branch_id = p_branch AND l.environment = v_env GROUP BY 1) q));
  v_out := jsonb_build_object('role', a.role, 'branch_id', p_branch, 'environment', v_env, 'counts', v_counts,
    'credential_active', EXISTS (SELECT 1 FROM public.satusehat_credentials c WHERE c.tenant_id = a.tenant_id AND c.branch_id = p_branch
                                   AND c.environment = v_env AND c.revoked_at IS NULL));
  IF a.role = 'admin_pusat' THEN
    RETURN v_out;
  END IF;
  IF a.role = 'doctor' THEN
    -- his own signed visits: per visit the item state and each resource type's link states (codes only)
    RETURN v_out - 'counts' || jsonb_build_object('mine', (SELECT coalesce(jsonb_agg(jsonb_build_object('visit_id', c.visit_id, 'patient_id', c.patient_id,
        'patient_name', (SELECT p.full_name FROM public.patients p WHERE p.tenant_id = c.tenant_id AND p.id = c.patient_id), 'signed_at', c.signed_at,
        'state', (SELECT x.state || coalesce(':' || x.hold_reason, '') FROM public.satusehat_outbox x WHERE x.tenant_id = c.tenant_id AND x.visit_id = c.visit_id
                   ORDER BY x.revision DESC, x.created_at DESC LIMIT 1),
        'links', (SELECT coalesce(jsonb_agg(jsonb_build_object('type', l.fhir_type, 'status', l.status, 'reason', l.status_reason,
                    -- plan r4 §9: the rejected code (the latest attempt's code only; never the provider body)
                    'error_code', CASE WHEN l.status = 'failed' THEN (SELECT t0.error_code FROM public.satusehat_attempts t0 WHERE t0.tenant_id = l.tenant_id
                                   AND t0.link_id = l.id ORDER BY t0.started_at DESC, t0.id DESC LIMIT 1) END) ORDER BY l.fhir_type, l.local_key), '[]'::jsonb)
                  FROM public.satusehat_links l WHERE l.tenant_id = c.tenant_id AND l.visit_id = c.visit_id AND l.environment = v_env))
      ORDER BY c.signed_at DESC), '[]'::jsonb)
      FROM (SELECT * FROM public.satusehat_visit_context c0 WHERE c0.tenant_id = a.tenant_id AND c0.branch_id = p_branch AND c0.doctor_staff_id = a.staff_id
             ORDER BY c0.signed_at DESC LIMIT 50) c));
  END IF;
  -- owner, manager, facility head, records officer: the exceptions (codes and FHIR paths only; the body is clinical)
  -- the patient (the way to the record) only for the facility head, the one clinical role here (UX-23 "Rejected item → record")
  v_out := v_out || jsonb_build_object('exceptions', (SELECT coalesce(jsonb_agg(jsonb_build_object('visit_id', l.visit_id, 'type', l.fhir_type,
      'status', l.status, 'reason', l.status_reason, 'attempt_id', t.id, 'error_code', t.error_code, 'error_path', t.error_path, 'at', l.updated_at,
      'patient_id', CASE WHEN a.role = 'facility_head' THEN (SELECT c.patient_id FROM public.satusehat_visit_context c WHERE c.tenant_id = l.tenant_id AND c.visit_id = l.visit_id) END)
      ORDER BY l.updated_at DESC), '[]'::jsonb)
    FROM (SELECT * FROM public.satusehat_links l0 WHERE l0.tenant_id = a.tenant_id AND l0.branch_id = p_branch AND l0.environment = v_env
           AND l0.status IN ('failed','exception','withdrawal_pending','held') ORDER BY l0.updated_at DESC LIMIT 100) l
    LEFT JOIN LATERAL (SELECT t0.id, t0.error_code, t0.error_path FROM public.satusehat_attempts t0 WHERE t0.tenant_id = l.tenant_id AND t0.link_id = l.id
                        ORDER BY t0.started_at DESC, t0.id DESC LIMIT 1) t ON true),
    'held_items', (SELECT coalesce(jsonb_agg(jsonb_build_object('visit_id', x.visit_id, 'reason', x.hold_reason, 'since', x.created_at) ORDER BY x.created_at DESC), '[]'::jsonb)
      FROM (SELECT * FROM public.satusehat_outbox x0 WHERE x0.tenant_id = a.tenant_id AND x0.branch_id = p_branch AND x0.state = 'held'
             ORDER BY x0.created_at DESC LIMIT 100) x));
  v_out := v_out || jsonb_build_object(
      'identity_queue', (SELECT coalesce(jsonb_agg(jsonb_build_object('patient_id', p.id, 'mrn', p.mrn, 'name', p.full_name, 'reason', i.reason,
          'state', i.state) ORDER BY p.mrn), '[]'::jsonb)
        FROM public.satusehat_patient_identity i JOIN public.patients p ON p.tenant_id = i.tenant_id AND p.id = i.patient_id
       WHERE i.tenant_id = a.tenant_id AND i.is_current AND i.state IN ('review','unresolvable')
         AND EXISTS (SELECT 1 FROM public.satusehat_visit_context c WHERE c.tenant_id = i.tenant_id AND c.branch_id = p_branch
                       AND c.patient_id = ANY (public.patient_cluster(i.tenant_id, i.patient_id)))));
  IF a.role IN ('facility_head','records_officer') THEN
    v_out := v_out || jsonb_build_object(
      'no_room', (SELECT coalesce(jsonb_agg(jsonb_build_object('visit_id', c.visit_id, 'signed_at', c.signed_at) ORDER BY c.signed_at DESC), '[]'::jsonb)
        FROM public.satusehat_visit_context c WHERE c.tenant_id = a.tenant_id AND c.branch_id = p_branch AND c.room_id IS NULL),
      'rooms', (SELECT coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'name', r.name) ORDER BY r.name), '[]'::jsonb)
        FROM public.rooms r WHERE r.tenant_id = a.tenant_id AND r.branch_id = p_branch AND r.is_active));
  END IF;
  IF a.role IN ('owner','facility_head') THEN
    v_out := v_out || jsonb_build_object(
      'practitioners', (SELECT coalesce(jsonb_agg(jsonb_build_object('staff_id', s.id, 'name', s.display_name,
          'ihs', (SELECT l.ihs_practitioner_id FROM public.satusehat_practitioner_links l WHERE l.tenant_id = s.tenant_id AND l.staff_id = s.id AND l.ended_at IS NULL))
          ORDER BY s.display_name, s.id), '[]'::jsonb)
        FROM public.staff s WHERE s.tenant_id = a.tenant_id AND EXISTS (SELECT 1 FROM public.staff_branches sb WHERE sb.tenant_id = s.tenant_id AND sb.staff_id = s.id
               AND sb.branch_id = p_branch AND sb.role IN ('doctor','nurse','therapist','pharmacist','facility_head'))));
  END IF;
  IF a.role IN ('owner','manager','facility_head') THEN
    v_out := v_out || jsonb_build_object(
      'services', (SELECT coalesce(jsonb_agg(jsonb_build_object('item_id', i.id, 'code', i.code,
          'name', (SELECT v.name FROM public.catalog_versions v WHERE v.tenant_id = i.tenant_id AND v.item_id = i.id ORDER BY v.version DESC LIMIT 1),
          'map', (SELECT jsonb_build_object('code', m.code, 'display', m.display, 'validated', m.validated) FROM public.satusehat_code_maps m
                   WHERE m.tenant_id = i.tenant_id AND m.item_id = i.id AND m.kind = 'icd9cm' AND m.effective_to IS NULL))
          ORDER BY i.code), '[]'::jsonb)
        FROM public.catalog_items i WHERE i.tenant_id = a.tenant_id AND i.kind = 'service'));
  END IF;
  RETURN v_out;
END
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION public.satusehat_page(uuid) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION public.satusehat_page(uuid) TO clinic_app;--> statement-breakpoint

-- The provider's error body of one attempt (DATA-40: clinical class): the facility head of the branch only; audited as a clinical read.
CREATE FUNCTION public.satusehat_error_body(p_attempt uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  a record := public.satusehat_actor(ARRAY['facility_head']);
  e public.satusehat_errors;
BEGIN
  SELECT * INTO e FROM public.satusehat_errors x WHERE x.tenant_id = a.tenant_id AND x.attempt_id = p_attempt;
  IF e.attempt_id IS NULL THEN RAISE EXCEPTION 'ERR_NOT_FOUND: error not found' USING ERRCODE = 'P0002'; END IF;
  PERFORM public.satusehat_branch(a, e.branch_id);
  PERFORM public.audit_append('clinical_read', 'satusehat_error', e.id, 'success', 'satusehat_error_body');
  RETURN e.body;
END
$$;--> statement-breakpoint
REVOKE ALL ON FUNCTION public.satusehat_error_body(uuid) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION public.satusehat_error_body(uuid) TO clinic_app;
